"""Original explanations and exercises for real numbers."""
from .layout import p, rule, note, example, formulas, table, figure

BASE = 'https://www.yaklass.ru/p/algebra/10-klass/deistvitelnye-chisla-9102/'

SETS = figure('Как связаны числовые множества', '''<svg class="ms-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 680 340" role="img" aria-label="Натуральные числа входят в целые, целые — в рациональные. Действительные числа состоят из рациональных и иррациональных."><rect x="10" y="10" width="660" height="320" rx="24" fill="#f8fafc" stroke="#cbd5e1"/><text x="34" y="46" font-size="23" fill="#334155">ℝ — действительные числа</text><rect x="30" y="70" width="370" height="240" rx="20" fill="#eff6ff" stroke="#93c5fd"/><text x="48" y="102" font-size="21" fill="#1d4ed8">ℚ — рациональные</text><text x="48" y="132" font-size="19" fill="#475569">1/2; −0,75; 0,(3)</text><rect x="50" y="155" width="330" height="138" rx="18" fill="#ede9fe" stroke="#c4b5fd"/><text x="68" y="185" font-size="20" fill="#6d28d9">ℤ — целые: …, −2, −1, 0, …</text><rect x="70" y="208" width="290" height="66" rx="14" fill="white" stroke="#a78bfa"/><text x="90" y="248" font-size="21" fill="#6d28d9">ℕ: 1, 2, 3, …</text><rect x="418" y="70" width="230" height="240" rx="20" fill="#fff7ed" stroke="#fdba74"/><text x="437" y="111" font-size="20" fill="#9a3412">Иррациональные</text><text x="437" y="161" font-size="24" fill="#9a3412">√2; −√3; π</text><text x="437" y="210" font-size="17" fill="#7c2d12">Не представляются</text><text x="437" y="238" font-size="17" fill="#7c2d12">дробью m/n,</text><text x="437" y="266" font-size="17" fill="#7c2d12">где m ∈ ℤ, n ∈ ℕ</text></svg>''', 'Каждое натуральное число также целое, рациональное и действительное. Рациональные и иррациональные числа не пересекаются.')

LESSONS = [dict(
    slug='10-klass-naturalnye-chisla-povtorenie', title='Натуральные числа. Повторение', section=1, order=1,
    source=BASE+'naturalnye-chisla-povtorenie-11259',
    intro='Повторим свойства натуральных чисел, делимость, простые множители и деление с остатком. Научимся использовать эти идеи в вычислениях и задачах, где неизвестные должны быть натуральными.',
    parts=[
        ('Натуральные числа и действия с ними', p('Натуральные числа используют для счёта предметов. В этом курсе ℕ = {1, 2, 3, …}; нуль к натуральным числам не относим. Если нужны также нуль и отрицательные числа, используем множество целых чисел ℤ.') + rule('Сумма и произведение натуральных чисел натуральны. Разность и частное могут не быть натуральными: 4 − 7 = −3, а 3 : 2 = 1,5.') + p('Число и цифра — разные понятия: число 707 записано тремя цифрами, но в записи использованы только две разные цифры — 7 и 0.') + example('Пример 1. Подходящие значения', 'Если n ∈ ℕ и 2 &lt; n ≤ 6, то n принимает значения <strong>3, 4, 5, 6</strong>. Левая граница не включена, правая включена.')),
        ('Чётность и признаки делимости', p('Число a делится на положительное b, если a = bk для некоторого целого k. Для натуральных a и b это означает, что остаток равен нулю. Чётные числа имеют вид 2k, нечётные — 2k + 1.') + table(['Делитель', 'Признак', 'Пример'], [('2','Последняя цифра чётная','738 делится на 2'),('3 или 9','Сумма цифр делится на 3 или 9','7 + 3 + 8 = 18: 738 делится на 9'),('4','Число из двух последних цифр делится на 4','1316: 16 делится на 4'),('5 или 10','На конце 0 или 5; для 10 — только 0','735 делится на 5, 730 — на 10')]) + example('Пример 2. Восстановить цифру', 'Число 52a должно делиться на 6. Тогда оно делится и на 2, и на 3: a — чётная цифра, а 7 + a кратно 3. Из 0, 2, 4, 6, 8 подходят <strong>a = 2 и a = 8</strong>.') + note('Сумма двух нечётных чисел чётна, а произведение нечётно. Чтобы доказать это, запишите числа как 2k + 1 и 2m + 1.')),
        ('Простые числа и разложение на множители', p('Простое число имеет ровно два натуральных делителя: 1 и само число. Составное имеет больше двух. Число 1 не является ни простым, ни составным; 2 — единственное чётное простое число.') + rule('Любое натуральное число, большее 1, единственным образом раскладывается в произведение простых множителей, если не учитывать порядок множителей.') + example('Пример 3. Разложить 420', formulas('420 = 42 · 10 = 2 · 3 · 7 · 2 · 5', '<strong>420 = 2² · 3 · 5 · 7.</strong>') + 'Проверка: 4 · 3 · 5 · 7 = 420. Остановиться на 42 · 10 нельзя: оба множителя ещё составные.') + p('Для проверки простоты числа достаточно искать простые делители, не превосходящие его квадратного корня. Например, √97 &lt; 10: число 97 не делится на 2, 3, 5 и 7, поэтому оно простое.')),
        ('НОД и НОК', p('Наибольший общий делитель (НОД) — наибольшее натуральное число, на которое делятся оба числа. Наименьшее общее кратное (НОК) — наименьшее положительное число, делящееся на оба.') + rule('В НОД берём общие простые множители в меньших степенях. В НОК берём все простые множители в больших степенях.') + example('Пример 4. Найти НОД и НОК чисел 84 и 126', formulas('84 = 2² · 3 · 7; 126 = 2 · 3² · 7;', 'НОД(84, 126) = 2 · 3 · 7 = <strong>42</strong>;', 'НОК(84, 126) = 2² · 3² · 7 = <strong>252</strong>.') + 'Проверка: 42 · 252 = 84 · 126. Для любых двух натуральных чисел произведение НОД и НОК равно произведению самих чисел.') + example('Пример 5. Одинаковые наборы', 'Из 84 карандашей и 126 ручек составляют максимальное число одинаковых наборов без остатка. Число наборов делит оба количества: это НОД, то есть <strong>42 набора</strong>. В каждом — 2 карандаша и 3 ручки.')),
        ('Деление с остатком', rule('При делении целого a на натуральное b получаем a = bq + r, где q — целое число, а 0 ≤ r &lt; b. Для натурального a частное q может быть нулём.') + example('Пример 6. Проверить запись', '157 = 12 · 13 + 1, поэтому при делении 157 на 12 неполное частное равно 13, остаток — 1. Запись 157 = 12 · 12 + 13 верна как равенство, но не как деление с остатком: 13 ≥ 12.') + example('Пример 7. Остаток суммы', 'Если a = 7k + 3 и b = 7m + 6, то a + b = 7(k + m) + 9 = 7(k + m + 1) + 2. Остаток суммы при делении на 7 равен <strong>2</strong>.')),
        ('Степени и порядок вычислений', p('Для натурального n степень aⁿ — произведение n одинаковых множителей a. Сначала выполняют действия в скобках, затем возведение в степень, затем умножение и деление, после них — сложение и вычитание.') + formulas('aᵐ · aⁿ = aᵐ⁺ⁿ; (aᵐ)ⁿ = aᵐⁿ; (ab)ⁿ = aⁿbⁿ.', 'При a ≠ 0 и m &gt; n: aᵐ : aⁿ = aᵐ⁻ⁿ.') + example('Пример 8. Вычислить без больших чисел', '2⁷ · 2⁴ : 2⁸ = 2⁷⁺⁴⁻⁸ = 2³ = <strong>8</strong>. Складываем и вычитаем показатели, поскольку основания одинаковые.') + note('Нельзя заменять 2³ + 2⁴ на 2⁷. Здесь сложение чисел: 8 + 16 = 24.')),
        ('Натуральные решения уравнения', p('Условие x, y ∈ ℕ ограничивает возможные решения. Полезно разложить левую часть на множители и перечислить пары натуральных делителей.') + example('Пример 9. Найти x и y', 'Пусть xy + x = 18, где x, y ∈ ℕ. Выносим x: x(y + 1) = 18. Поскольку y ≥ 1, имеем y + 1 ≥ 2. Для x подходят делители 1, 2, 3, 6, 9. Получаем пары <strong>(1; 17), (2; 8), (3; 5), (6; 2), (9; 1)</strong>. При x = 18 получилось бы y = 0 — условие нарушено.')),
    ],
    tasks=[
        ('Выпишите натуральные числа из списка: −4; 0; 7; 12/3; 5/2.', '<p><strong>7 и 12/3 = 4.</strong> В принятом определении 0 ∉ ℕ; отрицательные и нецелые числа также не подходят.</p>'),
        ('Найдите цифру a, если число 43a делится на 9.', '<p>4 + 3 + a = 7 + a. Между 7 и 16 единственное кратное 9 — число 9, поэтому <strong>a = 2</strong>.</p>'),
        ('Разложите 360 на простые множители.', '<p>360 = 36 · 10 = 2² · 3² · 2 · 5 = <strong>2³ · 3² · 5</strong>.</p>'),
        ('Найдите НОД и НОК чисел 72 и 120.', '<p>72 = 2³ · 3², 120 = 2³ · 3 · 5. <strong>НОД = 24, НОК = 360</strong>. Проверка: 24 · 360 = 72 · 120.</p>'),
        ('Запишите деление 203 на 15 с остатком.', '<p><strong>203 = 15 · 13 + 8</strong>. Остаток 8 удовлетворяет условию 0 ≤ 8 &lt; 15.</p>'),
        ('Вычислите 3⁶ · 3² : 3⁵.', '<p>3⁶⁺²⁻⁵ = 3³ = <strong>27</strong>.</p>'),
        ('Число n при делении на 5 даёт остаток 4. Каков остаток числа 2n + 3?', '<p>n = 5k + 4. Тогда 2n + 3 = 10k + 11 = 5(2k + 2) + 1. <strong>Остаток 1.</strong></p>'),
        ('Найдите все пары натуральных x и y, если x(y + 2) = 12.', '<p>y + 2 ≥ 3, поэтому x ≤ 4 и x делит 12. При x = 1, 2, 3, 4 получаем соответственно y = 10, 4, 2, 1. <strong>(1; 10), (2; 4), (3; 2), (4; 1).</strong></p>'),
    ], summary='ℕ = {1, 2, 3, …}. Проверяйте делимость и условия на остаток. Разложение на простые множители помогает найти НОД, НОК и все натуральные решения. Учитывайте, что неизвестное из ℕ не может равняться нулю.'
), dict(
    slug='10-klass-racionalnye-chisla-povtorenie', title='Рациональные числа. Повторение', section=1, order=2,
    source=BASE+'ratcionalnye-chisla-povtorenie-11250',
    intro='Свяжем обыкновенные дроби с конечными и периодическими десятичными записями. Повторим вычисления, сравнение, нахождение середины отрезка и точные преобразования периодических дробей.',
    parts=[
        ('Что значит «рациональное число»', rule('Рациональное число представляется дробью m/n, где m ∈ ℤ, n ∈ ℕ. Множество рациональных чисел обозначают ℚ.') + p('Целые числа тоже рациональны: −7 = −7/1, а 0 = 0/1. Разные дроби могут задавать одно число: 2/3 = 4/6 = 10/15. Чтобы получить несократимую дробь, делят числитель и знаменатель на их НОД.') + example('Пример 1. Сократить дробь', '−84/126 = −(84 : 42)/(126 : 42) = <strong>−2/3</strong>. Знак минус можно поставить перед дробью или в числителе.')),
        ('Какая десятичная запись получится', p('Деление числителя на знаменатель либо заканчивается, либо даёт повторяющуюся группу цифр — период. Запись 0,(27) означает 0,272727…; запись 0,1(6) означает 0,16666….') + rule('В несократимой дроби десятичная запись конечна тогда и только тогда, когда знаменатель имеет только простые множители 2 и 5 (или равен 1). В остальных случаях запись бесконечная периодическая.') + table(['Дробь','Знаменатель','Десятичная запись'], [('7/40','40 = 2³ · 5','0,175'),('5/12','12 = 2² · 3','0,41(6)'),('2/11','11','0,(18)')]) + p('Почему обязательно возникает период? При делении на n возможны лишь остатки 0, 1, …, n − 1. Нулевой остаток завершает деление, а повтор ненулевого остатка запускает повтор тех же цифр.') + note('Перед проверкой знаменателя сократите дробь: 6/15 = 2/5 = 0,4, хотя исходный знаменатель делится на 3.')),
        ('Из периодической дроби в обыкновенную', example('Пример 2. Чистый период', formulas('x = 0,(27); 100x = 27,(27);', '100x − x = 27; 99x = 27;', '<strong>x = 27/99 = 3/11.</strong>') + 'Умножили на 100, поскольку в периоде две цифры. Бесконечные одинаковые хвосты при вычитании исчезают.') + example('Пример 3. Есть цифра до периода', formulas('x = 0,2(7); 10x = 2,(7); 100x = 27,(7);', '100x − 10x = 25; 90x = 25;', '<strong>x = 5/18.</strong>') + 'Обе записи сдвинули так, чтобы повторяющиеся хвосты начинались сразу после запятой.') + note('Равенство 0,(9) = 1 — точное. Если x = 0,(9), то 10x − x = 9, откуда x = 1. Число может иметь две десятичные записи.')),
        ('Действия с дробями', formulas('a/b + c/d = (ad + bc)/(bd);', 'a/b · c/d = ac/(bd);', '(a/b) : (c/d) = ad/(bc), если c ≠ 0.', 'Во всех формулах b ≠ 0 и d ≠ 0.') + p('При сложении удобно выбирать наименьший общий знаменатель. При умножении можно сократить множители числителя и знаменателя до вычислений. Деление заменяют умножением на обратную дробь.') + example('Пример 4. Несколько действий', formulas('(5/6 − 3/4) : (−1/8)', '= (10/12 − 9/12) · (−8)', '= (1/12) · (−8) = <strong>−2/3.</strong>'))),
        ('Сравнение и середина отрезка', p('Для дробей с положительными знаменателями сравнивают перекрёстные произведения. Например, 5/8 &lt; 7/11, поскольку 55 &lt; 56. Среди отрицательных чисел больше то, у которого меньше модуль: −5/8 &gt; −7/11.') + rule('Число, равноудалённое от различных a и b на числовой прямой, равно (a + b)/2. Если a &lt; b, эта середина строго между ними.') + example('Пример 5. Найти середину', 'Для a = −2/3 и b = 5/6 получаем (−2/3 + 5/6)/2 = (1/6)/2 = <strong>1/12</strong>. Расстояния до концов равны 3/4.') + p('Между любыми двумя различными рациональными числами есть рациональное число — их середина. Повторяя этот приём, получаем бесконечно много рациональных чисел в любом непустом интервале.')),
        ('Дроби и целые показатели степени', rule('При a ≠ 0: a⁰ = 1 и a⁻ⁿ = 1/aⁿ, где n ∈ ℕ. Отрицательный показатель означает переход к обратному числу, а не отрицательный результат.') + example('Пример 6. Знак и обратная дробь', '(−2/3)⁻² = (−3/2)² = <strong>9/4</strong>. Чётная степень отрицательного основания положительна. При нечётном показателе знак остаётся отрицательным.') + note('−2² = −4, но (−2)² = 4. В первой записи степень относится только к 2, во второй — ко всему числу −2. Нуль нельзя возводить в нулевую или отрицательную степень в используемых школьных правилах.')),
        ('Точные вычисления с периодом', example('Пример 7. Корень из периодической дроби', 'Вычислим √(0,(4)). Сначала 0,(4) = 4/9, затем √(4/9) = <strong>2/3</strong>. Замена на 0,444 даёт только приближение и меняет условие.') + example('Пример 8. Уравнение', 'Решим x + 0,1(6) = 0,75. Здесь 0,1(6) = 1/6 и 0,75 = 3/4. Значит, x = 3/4 − 1/6 = <strong>7/12</strong>. Проверка: 7/12 + 2/12 = 9/12 = 3/4.') + p('Сначала переходите к точным дробям, затем выполняйте действия. Округление используйте только тогда, когда в задаче требуется приближённый ответ.')),
    ],
    tasks=[
        ('Какие из чисел −8; 0; 0,(13); √49 рациональны?', '<p><strong>Все четыре</strong>: −8/1; 0/1; 13/99; √49 = 7.</p>'),
        ('Какие дроби имеют конечную десятичную запись: 9/24; 7/30; 11/125?', '<p>9/24 = 3/8 = 0,375; 11/125 = 0,088. <strong>Первая и третья</strong>. Дробь 7/30 несократима, знаменатель содержит 3.</p>'),
        ('Переведите 0,(36) в обыкновенную дробь.', '<p>100x − x = 36, откуда x = 36/99 = <strong>4/11</strong>.</p>'),
        ('Переведите 0,3(6) в обыкновенную дробь.', '<p>100x = 36,(6), 10x = 3,(6). Значит, 90x = 33 и <strong>x = 11/30</strong>.</p>'),
        ('Вычислите (7/12 − 1/3) : (−3/8).', '<p>7/12 − 4/12 = 1/4. Далее (1/4) · (−8/3) = <strong>−2/3</strong>.</p>'),
        ('Найдите число, равноудалённое от −3/4 и 5/6.', '<p>(−3/4 + 5/6)/2 = (1/12)/2 = <strong>1/24</strong>.</p>'),
        ('Вычислите (−3/5)⁻².', '<p>(−5/3)² = <strong>25/9</strong>. Минус в показателе переворачивает дробь, а чётная степень делает результат положительным.</p>'),
        ('Вычислите √(0,(1)) + 0,(6).', '<p>√(1/9) + 2/3 = 1/3 + 2/3 = <strong>1</strong>.</p>'),
    ], summary='Рациональное число — дробь целого числа и натурального. Его десятичная запись конечная или периодическая. Периодические дроби переводите в обыкновенные до вычислений; не заменяйте точные числа округлениями.'
), dict(
    slug='10-klass-irracionalnye-chisla-povtorenie', title='Иррациональные числа. Повторение', section=1, order=3,
    source=BASE+'irratcionalnye-chisla-povtorenie-11360',
    intro='Разберём, чем иррациональные числа отличаются от рациональных, как их сравнивать и оценивать. Проверим, когда сумма и произведение иррациональных чисел могут оказаться рациональными.',
    parts=[
        ('Иррациональные и действительные числа', rule('Иррациональное число нельзя записать в виде m/n, где m ∈ ℤ, n ∈ ℕ. Его десятичная запись бесконечная непериодическая. Рациональные и иррациональные числа вместе образуют ℝ — множество действительных чисел.') + p('Примеры: √2, √3, π. А √36 = 6 и 0,(123) = 123/999 рациональны. Наличие знака корня или длинной десятичной записи само по себе ничего не доказывает.') + SETS),
        ('Почему √2 — иррациональное число', p('Предположим обратное: √2 = m/n для несократимой дроби с натуральными m и n. Возведём равенство в квадрат: m² = 2n². Значит, m² чётно, а потому и m чётно: квадрат нечётного числа всегда нечётный.') + p('Пусть m = 2k. Тогда 4k² = 2n², откуда n² = 2k². Следовательно, n тоже чётно. Числитель и знаменатель делятся на 2, что противоречит несократимости дроби. Значит, исходное предположение неверно.') + rule('Для натурального a число √a рационально тогда и только тогда, когда a — квадрат натурального числа.') + example('Пример 1. Классификация', '√121 = 11 — рациональное число. Число 18 не является полным квадратом, поэтому √18 = 3√2 — иррациональное.')),
        ('Оценки без калькулятора', p('Сравним квадраты неотрицательных чисел. Из 4 &lt; 7 &lt; 9 следует 2 &lt; √7 &lt; 3. Уточним границы, проверяя десятые и сотые.') + example('Пример 2. Округлить √7 до сотых', formulas('2,64² = 6,9696; 2,65² = 7,0225;', '2,64 &lt; √7 &lt; 2,65;', '2,645² = 6,996025 &lt; 7, поэтому √7 &gt; 2,645.', '<strong>√7 ≈ 2,65</strong> при округлении до сотых.') + 'Последний шаг нужен, чтобы определить, по какую сторону от середины 2,645 находится число.') + note('Знак «=» означает точное равенство, знак «≈» — приближение. Запись √7 = 2,65 неверна.')),
        ('Сравнение иррациональных чисел', rule('Квадратный корень возрастает: для 0 ≤ a &lt; b верно √a &lt; √b. Возводить обе части сравнения в квадрат без изменения порядка можно, когда обе части неотрицательны.') + example('Пример 3. Разные записи', 'Сравним 3√2 и √19: 3√2 = √18, а 18 &lt; 19, значит <strong>3√2 &lt; √19</strong>. Для противоположных чисел порядок обратный: −3√2 &gt; −√19.') + example('Пример 4. Найти целые числа в интервале', 'Так как 3 &lt; √11 &lt; 4 и 7 &lt; √60 &lt; 8, в интервале (√11; √60) лежат целые числа <strong>4, 5, 6, 7</strong>.')),
        ('Сумма рационального и иррационального', p('Если r рационально, а α иррационально, то r + α иррационально. Иначе из рациональности суммы следовала бы рациональность α = (r + α) − r. Это противоречие.') + rule('Сумма рационального и иррационального числа иррациональна. Произведение ненулевого рационального и иррационального числа тоже иррационально.') + example('Пример 5. Условие о нуле', 'Числа 5 + √3 и −2√3 иррациональны. Но 0 · √3 = 0 рационально: условие о ненулевом множителе нельзя убирать.')),
        ('Два иррациональных числа: результат бывает разным', table(['Действие','Рациональный результат','Иррациональный результат'], [('Сумма','√2 + (−√2) = 0','√2 + √2 = 2√2'),('Произведение','√3 · √3 = 3','√2 · √3 = √6'),('Частное','√5 / √5 = 1','√10 / √5 = √2')]) + example('Пример 6. Сопряжённые выражения', '(√5 − 2)(√5 + 2) = (√5)² − 2² = 5 − 4 = <strong>1</strong>. Оба множителя иррациональны, результат рационален.') + note('Нельзя заранее объявлять сумму или произведение двух иррациональных чисел иррациональным. Нужно исследовать конкретное выражение.')),
        ('Точка на прямой и точная длина', p('Каждому действительному числу соответствует точка числовой прямой. Иррациональные числа заполняют те точки, которым не соответствуют рациональные дроби. Например, диагональ квадрата со стороной 1 имеет точную длину √2 по теореме Пифагора.') + example('Пример 7. Длина и приближение', 'Если сторона квадрата равна 3 см, то диагональ d = √(3² + 3²) = √18 = <strong>3√2 см</strong>. До сотых это примерно 4,24 см. Для дальнейших точных вычислений удобнее сохранить 3√2.') + p('Между любыми различными действительными числами есть и рациональные, и иррациональные числа. Например, между 1,4 и 1,5 расположены рациональное 1,45 и иррациональное √2, потому что 1,4² &lt; 2 &lt; 1,5².')),
    ],
    tasks=[
        ('Какие числа иррациональны: √81; √20; 0,(7); π − 3?', '<p><strong>√20 и π − 3.</strong> √81 = 9; 0,(7) = 7/9. Число 20 не полный квадрат, а вычитание рационального 3 из π сохраняет иррациональность.</p>'),
        ('Между какими соседними целыми числами находится √34?', '<p>5² = 25 &lt; 34 &lt; 36 = 6², значит <strong>5 &lt; √34 &lt; 6</strong>.</p>'),
        ('Сравните 2√7 и 3√3.', '<p>Оба числа положительны. Их квадраты равны 28 и 27, поэтому <strong>2√7 &gt; 3√3</strong>.</p>'),
        ('Найдите все целые числа в интервале (−√10; √17).', '<p>−4 &lt; −√10 &lt; −3 и 4 &lt; √17 &lt; 5. Ответ: <strong>−3, −2, −1, 0, 1, 2, 3, 4</strong>.</p>'),
        ('Вычислите (√11 − 3)(√11 + 3).', '<p>11 − 9 = <strong>2</strong>, по формуле разности квадратов.</p>'),
        ('Приведите два иррациональных числа, сумма которых равна 7.', '<p>Например, <strong>√2 и 7 − √2</strong>. Оба иррациональны, а сумма равна 7.</p>'),
        ('Может ли произведение двух различных иррациональных чисел равняться 6?', '<p><strong>Да:</strong> √2 · 3√2 = 6. Оба множителя иррациональны и различны.</p>'),
        ('Докажите, что 1,73 &lt; √3 &lt; 1,74. Округлите √3 до сотых.', '<p>1,73² = 2,9929 &lt; 3 &lt; 3,0276 = 1,74². Середина 1,735 имеет квадрат 3,010225 &gt; 3, значит √3 &lt; 1,735. При округлении получаем <strong>1,73</strong>.</p>'),
    ], summary='ℝ состоит из рациональных и иррациональных чисел. Для сравнения корней учитывайте знаки. Сохраняйте точные значения до последнего шага. Действия с двумя иррациональными числами могут дать как рациональный, так и иррациональный результат.'
)]
